SELECT *, CORR(credit_limit, age) OVER (PARTITION BY city) AS corr_credit_limit_age, FIRST_VALUE(segment, TRUE) OVER (ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_segment, CORR(credit_limit, age) OVER (PARTITION BY segment) AS corr_credit_limit_age_2, CUME_DIST() OVER (PARTITION BY city ORDER BY credit_limit DESC NULLS FIRST) AS credit_limit_cume_dist FROM customers WHERE email IS NULL;
